/* ---------- every action registered in this layer goes through the policy and context wrappers ---------- */
['loop-new','loop-verbal','loop-chase','loop-withdraw','loop-client','loop-duty','cockpit-money','cal-nav','cal-view','cal-kind','contract-edit','vendor-compliance'].forEach(k=>{const f=ACTS[k];ACTS[k]=function(ctx){if(!actAllowed(k,ctx))return denyAct(k);const prev=CURRENT_ACT,prevC=CURRENT_CTX;CURRENT_ACT=k;CURRENT_CTX=ctx||CURRENT_CTX;try{return f.apply(this,arguments)}finally{CURRENT_ACT=prev;CURRENT_CTX=prevC}}});
['cal-event','cal-person'].forEach(k=>{const f=ACTS_CHANGE[k];ACTS_CHANGE[k]=function(el){if(!actAllowed(k,{el}))return denyAct(k);return f.apply(this,arguments)}});

